'use strict';

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var canUseNative = require( './can_use_native.js' );
var main = require( './main.js' );


// MAIN //

/**
* Returns a tridiagonal factorization interface with native dispatch.
*
* @private
* @param {Function} addon - native ndarray kernel
* @returns {Function} factorization interface
*/
function factory( addon ) {
	setReadOnly( dgttrf, 'ndarray', ndarray );
	return dgttrf;

	/**
	* Computes a tridiagonal LU factorization.
	*
	* @private
	* @param {NonNegativeInteger} N - matrix order
	* @param {Float64Array} DL - subdiagonal elements
	* @param {Float64Array} D - diagonal elements
	* @param {Float64Array} DU - superdiagonal elements
	* @param {Float64Array} DU2 - output second superdiagonal
	* @param {Int32Array} IPIV - output pivot indices
	* @returns {integer} status code
	*/
	function dgttrf( N, DL, D, DU, DU2, IPIV ) {
		var args = [ N, DL, 1, 0, D, 1, 0, DU, 1, 0, DU2, 1, 0, IPIV, 1, 0 ];
		if ( canUseNative( args ) ) {
			return addon.apply( null, args );
		}
		return main( N, DL, D, DU, DU2, IPIV );
	}

	/**
	* Computes a tridiagonal LU factorization using alternative indexing semantics.
	*
	* @private
	* @param {NonNegativeInteger} N - matrix order
	* @param {Float64Array} DL - subdiagonal elements
	* @param {integer} strideDL - stride length for DL
	* @param {NonNegativeInteger} offsetDL - starting index for DL
	* @param {Float64Array} D - diagonal elements
	* @param {integer} strideD - stride length for D
	* @param {NonNegativeInteger} offsetD - starting index for D
	* @param {Float64Array} DU - superdiagonal elements
	* @param {integer} strideDU - stride length for DU
	* @param {NonNegativeInteger} offsetDU - starting index for DU
	* @param {Float64Array} DU2 - output second superdiagonal
	* @param {integer} strideDU2 - stride length for DU2
	* @param {NonNegativeInteger} offsetDU2 - starting index for DU2
	* @param {Int32Array} IPIV - output pivot indices
	* @param {integer} strideIPIV - stride length for IPIV
	* @param {NonNegativeInteger} offsetIPIV - starting index for IPIV
	* @returns {integer} status code
	*/
	function ndarray( N, DL, strideDL, offsetDL, D, strideD, offsetD, DU, strideDU, offsetDU, DU2, strideDU2, offsetDU2, IPIV, strideIPIV, offsetIPIV ) { // eslint-disable-line max-len, max-params
		var args = [ N, DL, strideDL, offsetDL, D, strideD, offsetD, DU, strideDU, offsetDU, DU2, strideDU2, offsetDU2, IPIV, strideIPIV, offsetIPIV ];
		if ( canUseNative( args ) ) {
			return addon.apply( null, args );
		}
		return main.ndarray.apply( null, args );
	}
}


// EXPORTS //

module.exports = factory;
